for group,entries in groups.items():
 if group.startswith('resource /'):
  key=group.split(' / ',1)[1]; targets=family[key].split();familyrows.append(dict(family=key,classes=targets,source=chosen[group],evidenceLevel=source_status.get(chosen[group],'Navigation and selected reference'),mappingStatus='Represented',shapeCoverage=[x+'Shape' for x in targets]))
